import {escapeHTML as esc} from './transfer-ui.mjs';
import {FUNDING_ASSETS,toUnits,fromUnits} from './funding-catalog.mjs';
const exact=(value,asset)=>fromUnits(toUnits(value||'0',asset,{allowZero:true}),asset);
export function accountTableHTML(){return '<section class="deposit-panel admin-accounts"><div class="finance-section-heading"><div><h2>All Registered Accounts</h2><p class="transfer-caption">Edit available balances in the table. Reserved withdrawals are read-only. Every saved change requires a reason and is audited.</p></div><span id="account-table-total">0 accounts</span></div><form id="account-table-search-form" class="account-table-controls"><label for="account-table-search">Search name or email<input id="account-table-search" maxlength="254" placeholder="All registered users"></label><label for="account-table-asset">Balance asset<select id="account-table-asset">'+Object.keys(FUNDING_ASSETS).map(s=>'<option '+(s==='USDT'?'selected':'')+'>'+s+'</option>').join('')+'</select></label><button type="submit" class="secondary-button">Search / Refresh</button></form><div class="account-table-scroll"><table class="account-balance-table"><caption class="sr-only">Registered users and editable available balances</caption><thead><tr><th scope="col">Account</th><th scope="col">Email</th><th scope="col">Email status</th><th scope="col" id="account-available-heading">Available USDT</th><th scope="col" id="account-reserved-heading">Reserved USDT</th><th scope="col">Reason for change</th><th scope="col">Save</th></tr></thead><tbody id="account-table-body"><tr><td colspan="7">Sign in as an administrator to view registered accounts.</td></tr></tbody></table></div><div class="transfer-actions"><button id="account-table-prev" class="transfer-back" type="button" disabled>← Previous</button><span id="account-table-page">Page 1</span><button id="account-table-next" class="transfer-back" type="button" disabled>Next →</button></div><p id="account-table-feedback" class="transfer-caption" role="status"></p></section>';}
export function mountAccountTable(host,service,onSaved=()=>{}){let page=0,rows=[],total=0,generation=0;const q=s=>host.querySelector(s);if(!service){host.querySelectorAll('input,select,button').forEach(el=>el.disabled=true);return;}const pending=new Map();
 function render(){const asset=q('#account-table-asset').value;q('#account-table-total').textContent=total+' registered account'+(total===1?'':'s');q('#account-table-page').textContent='Page '+(page+1);q('#account-available-heading').textContent='Available '+asset;q('#account-reserved-heading').textContent='Reserved '+asset;q('#account-table-prev').disabled=page===0;q('#account-table-next').disabled=(page+1)*25>=total;q('#account-table-body').innerHTML=rows.length?rows.map(a=>{const b=a.balances.find(b=>b.asset===asset),name=[a.first_name,a.last_name].filter(Boolean).join(' ')||'Unnamed account';return '<tr data-account="'+a.id+'"><td><strong>'+esc(name)+'</strong><small>'+esc(a.id)+'</small></td><td>'+esc(a.email||'No email')+'</td><td>'+esc(a.email_confirmed_at?'Verified':'Pending')+'</td><td><input data-cell="balance" inputmode="decimal" aria-label="Available '+asset+' balance for '+esc(a.email||a.id)+'" value="'+exact(b?.available,asset)+'"></td><td>'+exact(b?.reserved,asset)+'</td><td><input data-cell="reason" maxlength="2000" aria-label="Balance change reason for '+esc(a.email||a.id)+'" placeholder="Required reason"><small data-cell="feedback" role="status"></small></td><td><button type="button" class="secondary-button" data-save-account="'+a.id+'">Save</button></td></tr>';}).join(''):'<tr><td colspan="7">No accounts match your search.</td></tr>';}
 async function load(){const id=++generation;q('#account-table-feedback').textContent='Refreshing account table…';try{const data=await service.accountsPage(q('#account-table-search').value.trim(),page);if(id!==generation||!host.isConnected)return;rows=data.accounts;total=data.total;render();q('#account-table-feedback').textContent='All registered accounts are included, including users with no credited balance. Showing up to 25 per page.';}catch(e){q('#account-table-feedback').textContent=e.message;}}
 q('#account-table-search-form').onsubmit=e=>{e.preventDefault();page=0;load();};q('#account-table-asset').onchange=render;q('#account-table-prev').onclick=()=>{if(page>0){page--;load();}};q('#account-table-next').onclick=()=>{page++;load();};
 host.addEventListener('click',async e=>{const button=e.target.closest('[data-save-account]');if(!button||button.disabled)return;const tr=button.closest('tr'),account=rows.find(a=>a.id===button.dataset.saveAccount),asset=q('#account-table-asset').value,balanceInput=tr.querySelector('[data-cell=balance]'),reasonInput=tr.querySelector('[data-cell=reason]'),message=tr.querySelector('[data-cell=feedback]');button.disabled=true;balanceInput.disabled=true;reasonInput.disabled=true;try{const amount=exact(balanceInput.value,asset),expected_available=exact(account.balances.find(b=>b.asset===asset)?.available,asset),note=reasonInput.value.trim();if(amount===expected_available)throw Error('No balance change to save.');if(note.length<5)throw Error('Enter a reason of at least five characters.');const fingerprint=[account.id,asset,amount,expected_available,note].join('|');let id=pending.get(fingerprint);if(!id){id=crypto.randomUUID();pending.set(fingerprint,id);}await service.execute('set_available_balance',{account_id:account.id,asset,amount,expected_available,note},id);pending.delete(fingerprint);await load();await onSaved();q('#account-table-feedback').textContent='Saved '+asset+' balance for '+(account.email||account.id)+'. Change recorded in the wallet audit trail.';}catch(e){message.textContent=e.message;}finally{button.disabled=false;balanceInput.disabled=false;reasonInput.disabled=false;}});
 load();return {refresh:load};}
